// ---- Edit after importing ----
const ALLOWED_CHAT_IDS = ['YOUR_TELEGRAM_CHAT_ID']; // only these chats may use the bot (it spends API credits)
const MODEL = 'gpt-4o-mini';
const MAX_MB = 20; // Telegram bots can download files up to 20 MB
// ------------------------------
const msg = $input.first().json.message || {};
const chatId = msg.chat?.id;
if (!chatId || !ALLOWED_CHAT_IDS.map(String).includes(String(chatId))) return []; // silently ignore strangers
return [{ json: {
  model: MODEL, chat_id: chatId, message_id: msg.message_id,
  text: (msg.text || msg.caption || '').trim().slice(0, 2000),
  max_bytes: MAX_MB * 1024 * 1024,
  file_id: (msg.video || msg.audio || msg.voice || msg.video_note || msg.document)?.file_id || null,
  file_size: (msg.video || msg.audio || msg.voice || msg.video_note || msg.document)?.file_size || 0,
  mime: (msg.video || msg.audio || msg.voice || msg.document)?.mime_type || '',
  received_at: new Date((msg.date || Date.now() / 1000) * 1000).toISOString(),
} }];

const j = $input.first().json;
let problem = null;
if (!j.file_id) problem = 'Kirim file video atau audio (maks 20 MB) ke bot ini, nanti aku ringkas dan cariin bagian yang enak dijadiin klip.';
else if (j.file_size > j.max_bytes) problem = 'File-nya kegedean. Bot Telegram cuma bisa download maks 20 MB, kompres dulu ya.';
else if (j.mime && !/^(video|audio)\//.test(j.mime)) problem = 'Format file-nya bukan video/audio.';
return [{ json: { ...j, problem } }];

const t = $input.first().json;
const segs = Array.isArray(t.segments) ? t.segments : [];
const fmt = (s) => `[${Math.round(s.start)}-${Math.round(s.end)}] ${String(s.text || '').trim()}`;
let transcript = segs.length ? segs.map(fmt).join('\n') : String(t.text || '');
if (!transcript.trim()) throw new Error('Empty transcript (no speech found?)');
transcript = transcript.slice(0, 40000); // ~10k tokens cap per video
const duration = Number(t.duration) || (segs.length ? segs[segs.length - 1].end : 0);
return [{ json: { transcript, duration, language: t.language || '' } }];

let d = {};
try { d = JSON.parse($input.first().json.choices[0].message.content); } catch (e) { d = { summary: 'Ringkasan gagal dibuat.' }; }
if (!d || typeof d !== 'object' || Array.isArray(d)) d = { summary: 'Ringkasan gagal dibuat.' };
const ctx = $('Config').first().json;
const str = (v, n) => typeof v === 'string' ? v.trim().slice(0, n) : '';
const list = (v, n) => (Array.isArray(v) ? v : []).map((x) => str(x, 300)).filter(Boolean).slice(0, n);
const dur = $('Build Timestamped Transcript').first().json.duration || Infinity;
const hms = (s) => new Date(s * 1000).toISOString().slice(11, 19);
const clips = (Array.isArray(d.clips) ? d.clips : []).map((c) => ({
  start: Math.max(0, Number(c?.start)), end: Math.min(dur, Number(c?.end)), title: str(c?.title, 100), hook: str(c?.hook, 200) }))
  .filter((c) => Number.isFinite(c.start) && Number.isFinite(c.end) && c.end - c.start >= 5 && c.end - c.start <= 180)
  .slice(0, 3)
  .map((c, i) => ({ ...c, range: `${hms(c.start)}–${hms(c.end)}`,
    ffmpeg: `ffmpeg -ss ${c.start} -to ${c.end} -i input.mp4 -vf "crop=ih*9/16:ih,scale=1080:1920" -c:a aac clip${i + 1}.mp4` }));
return [{ json: { ...ctx, title: str(d.title, 120) || 'Video', summary: str(d.summary, 1500),
  key_points: list(d.key_points, 8), action_items: list(d.action_items, 8), clips } }];

const clean = (v, max = 500) => {
  if (v === null || v === undefined) return '';
  let s = String(v).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').slice(0, max);
  if (/^[=+\-@\t\r]/.test(s)) s = "'" + s; // block spreadsheet formula injection
  return s;
};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const s = $input.first().json;
const bullets = (a) => a.map((x) => '• ' + esc(x)).join('\n');
const clipsTxt = s.clips.map((c, i) => `🎬 <b>Klip ${i + 1}</b> ${c.range}: ${esc(c.title)}\n<code>${esc(c.ffmpeg)}</code>`).join('\n\n');
const message = [`📼 <b>${esc(s.title)}</b>`, esc(s.summary),
  s.key_points.length ? '<b>Poin penting</b>\n' + bullets(s.key_points) : '',
  s.action_items.length ? '<b>To-do</b>\n' + bullets(s.action_items) : '',
  clipsTxt ? '<b>Kandidat klip pendek</b>\n' + clipsTxt : ''].filter(Boolean).join('\n\n').slice(0, 4000);
return [{ json: { chat_id: s.chat_id, message, row: { created_at: new Date().toISOString(), title: clean(s.title, 120),
  summary: clean(s.summary, 1500), key_points: clean(s.key_points.join(' | '), 2000),
  action_items: clean(s.action_items.join(' | '), 2000), clips: clean(s.clips.map((c) => `${c.range} ${c.title}`).join(' | '), 1000) } } }];
